mapper.select:
select

    
        date_format(c.create_time, '%c') groupKey,
    
    
        date_format(c.create_time, '%e') groupKey,
    

sum(c.quantity * a.net_weight) mete
from mes_building_complete c
inner join tech_artifact a on a.id = c.product_id and c.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()}

    and c.bool_delete_enum = 0
    
        
            and date_format(c.create_time, '%Y') = #{year}
        
        
            and date_format(c.create_time, '%Y-%m') = #{month}
        
    
    
        and c.project_id = #{projectId}
    
    
        and c.factory_id = #{factoryId}
    

group by groupKey

select

    
        date_format(c.create_time, '%c') groupKey,
    
    
        date_format(c.create_time, '%e') groupKey,
    

sum(c.quantity * a.length) mete
from mes_building_complete c
inner join tech_enclosure a on a.id = c.product_id and c.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ENCLOSURE.getType()}

    and c.bool_delete_enum = 0
    
        
            and date_format(c.create_time, '%Y') = #{year}
        
        
            and date_format(c.create_time, '%Y-%m') = #{month}
        
    
    
        and c.factory_id = #{factoryId}
    

group by groupKey

select
a.category groupKey,
sum(c.quantity * a.length) mete
from mes_building_complete c
inner join tech_enclosure a on a.id = c.product_id and c.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ENCLOSURE.getType()}

    and c.bool_delete_enum = 0
    
        
            and date_format(c.create_time, '%Y-%m') = #{month}
        
        
            and date_format(c.create_time, '%Y-%m-%d') = #{date}
        
    
    
        and c.factory_id = #{factoryId}
    

group by groupKey

select
a.plate groupKey,
sum(c.quantity * a.length) mete
from mes_building_complete c
inner join tech_enclosure a on a.id = c.product_id and c.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ENCLOSURE.getType()}

    and c.bool_delete_enum = 0
    
        
            and date_format(c.create_time, '%Y-%m') = #{month}
        
        
            and date_format(c.create_time, '%Y-%m-%d') = #{date}
        
    
    
        and c.factory_id = #{factoryId}
    

group by groupKey

select a.name, a.serial_number, a.material, a.specification, a.length length, a.net_weight, a.gross_weight, c.quantity, a.net_weight * c.quantity total_net_weight, a.gross_weight * c.quantity total_gross_weight, c.create_time, p.id 'project.id', p.name 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', m.`id` 'monomer.id', m.`name` 'monomer.name' from mes_building_complete c inner join tech_artifact a on a.id = c.product_id and c.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()} and a.bool_delete_enum = 0 inner join contract_project p on p.id = a.project_id and p.bool_delete_enum = 0 inner join plan_monomer m on m.id = a.monomer_id and m.bool_delete_enum = 0 where c.bool_delete_enum = 0
and c.project_id = #{projectId}
and date_format(c.create_time, '%Y-%m') = #{month}

SELECT
IFNULL( SUM( cm.quantity * a.net_weight / 1000 ), 0 ) AS completed_mete
FROM
mes_building_complete AS cm
INNER JOIN tech_artifact AS a ON cm.product_id = a.id AND a.bool_delete_enum = 0
WHERE
cm.bool_delete_enum = 0
AND cm.task_type_enum = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()}

    AND cm.monomer_id = #{monomerId}


    AND cm.area_id = #{areaId}

select.if:
SELECT IFNULL(classification.classification_name,'其他') typeName, classification.artifact_type as artifactType, IFNULL( sum( complete.quantity * product.net_weight ), 0 ) yield FROM mes_building_complete complete LEFT JOIN tech_artifact product ON product.id = complete.product_id AND product.bool_delete_enum = 0 LEFT JOIN sys_structure_classification classification ON product.structure_class_id = classification.id AND classification.bool_delete_enum = 0 WHERE complete.bool_delete_enum = 0 AND complete.task_type_enum = #{productType} AND DATE_FORMAT( complete.create_time, '%Y' )= DATE_FORMAT( #{dateTime}, '%Y' )
AND EXISTS( select 1 from project_branch_company_link pbcl where pbcl.bool_delete_enum = FALSE AND pbcl.branch_company_level = 2 and pbcl.branch_company_id = #{branchCompanyId} and pbcl.project_id = complete.project_id )
AND complete.project_id in
#{projectId}
GROUP BY classification.id;

mapper.select:
SELECT DATE_FORMAT( complete.create_time, "%m" ) `month`, IFNULL( sum( complete.quantity * artifact.net_weight ), 0 ) complete FROM mes_building_complete complete LEFT JOIN tech_artifact artifact ON artifact.id = complete.product_id
task_type_enum = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()}
AND complete.factory_id = #{factoryId}
AND complete.bool_delete_enum = 0 AND DATE_FORMAT( complete.create_time, "%Y" )= DATE_FORMAT(#{dateTime}, "%Y" )
GROUP BY month ORDER BY month

SELECT line.id 'productionLine.id', line.`name`'productionLine.name', tulink.user_name 'teamName', a.create_time date, cp.id 'project.id', cp.NAME 'project.name', cp.serial_number 'project.serialNumber', cp.short_name 'project.shortName', pl.id 'monomer.id', pl.NAME 'monomer.name', pa.id 'area.id', pa.NAME 'area.name', a.task_id, a.NAME, a.specification, a.serial_number, a.material, a.length, a.net_weight, a.gross_weight, a.quantity, a.surface_area, a.total_surface_area, a.total_net_weight, a.total_gross_weight, a.order_number FROM ( SELECT c.project_id, c.monomer_id, c.area_id, c.task_id, DATE(c.create_time) create_time, c.production_line_id, c.team_id, ta.`name` NAME, ta.serial_number, ta.specification, ta.material, ta.length, ta.net_weight, ta.gross_weight, sum( c.quantity ) quantity, ta.surface_area / 1000000 AS surface_area, IFNULL( SUM(ta.surface_area * c.quantity), 0 ) / 1000000 AS total_surface_area, IFNULL( SUM( c.quantity * ta.net_weight ), 0 ) total_net_weight, IFNULL( SUM( c.quantity * ta.gross_weight ), 0 ) total_gross_weight, taskOrder.order_number FROM `mes_building_complete` c LEFT JOIN tech_artifact ta ON ta.id = c.product_id LEFT JOIN mes_building_task task ON task.id = c.task_id LEFT JOIN mes_building_task_order taskOrder ON taskOrder.id = task.task_order_id AND ta.bool_delete_enum = 0 WHERE c.bool_delete_enum = 0 AND c.task_type_enum = 2
AND date_format (c.create_time, '%Y-%m-%d') >= date_format(#{startTime}, '%Y-%m-%d')
AND date_format (c.create_time, '%Y-%m-%d') <= date_format(#{endTime}, '%Y-%m-%d')
AND c.project_id=#{projectId}
AND c.workshop_id=#{workShopId}
AND c.production_line_id=#{productionLineId}
GROUP BY DATE(c.create_time), c.team_id, c.production_line_id, c.project_id, c.monomer_id, c.area_id, c.task_id, ta.id ) a LEFT JOIN mes_building_production_line line ON line.id = a.production_line_id LEFT JOIN mes_building_team_user_link tulink on tulink.team_id = a.team_id and tulink.bool_leader_enum = 1 and tulink.bool_delete_enum = 0 LEFT JOIN contract_project cp ON cp.id = a.project_id LEFT JOIN plan_monomer pl ON pl.id = a.monomer_id LEFT JOIN plan_area pa ON pa.id = a.area_id

select.if:
SELECT DATE_FORMAT( mc.create_time, '%Y-%m' ) date, IFNULL( sum( ta.net_weight * mc.quantity ), 0 ) totalNetWeight, IFNULL( sum( ta.gross_weight * mc.quantity ), 0 ) totalGrossWeight FROM mes_building_complete mc LEFT JOIN tech_artifact ta ON mc.product_id = ta.id AND ta.bool_delete_enum = false WHERE mc.task_type_enum = 2 AND mc.bool_delete_enum = false AND date_format(mc.create_time, '%Y') = date_format(#{dateTime}, '%Y')
AND mc.workshop_id = #{workShopId}
AND mc.production_line_id = #{productionLineId}
GROUP BY DATE_FORMAT( mc.create_time, '%Y-%m' )

SELECT DATE_FORMAT( mc.create_time, '%Y-%m-%d' ) date, IFNULL( sum( ta.net_weight * mc.quantity ), 0 ) totalNetWeight, IFNULL( sum( ta.gross_weight * mc.quantity ), 0 ) totalGrossWeight FROM mes_building_complete mc LEFT JOIN tech_artifact ta ON mc.product_id = ta.id AND ta.bool_delete_enum = false WHERE mc.task_type_enum = 2 AND mc.bool_delete_enum = false AND date_format(mc.create_time, '%Y/%m') = date_format(#{dateTime}, '%Y/%m')
AND mc.workshop_id = #{workShopId}
AND mc.production_line_id = #{productionLineId}
GROUP BY DATE_FORMAT( mc.create_time, '%Y-%m-%d' )

mapper.select:
SELECT cp.id 'project.id', cp.`name`'project.name', cp.short_name'project.shortName', cp.serial_number'project.serialNumber', IFNULL( sum( ta.net_weight * mc.quantity ), 0 ) totalNetWeight, IFNULL( sum( ta.gross_weight * mc.quantity ), 0 ) totalGrossWeight FROM mes_building_complete mc LEFT JOIN tech_artifact ta ON mc.product_id = ta.id AND ta.bool_delete_enum = false LEFT JOIN contract_project cp ON cp.id = mc.project_id WHERE mc.task_type_enum = 2 AND mc.bool_delete_enum = false AND date_format(mc.create_time, '%Y/%m') = date_format(#{dateTime}, '%Y/%m')
AND mc.workshop_id = #{workShopId}
AND mc.production_line_id = #{productionLineId}
GROUP BY cp.id

SELECT DATE_FORMAT( bc.create_time, '%Y%m' ) month, SUM( a.net_weight * bc.quantity ) mete FROM `mes_building_complete` bc LEFT JOIN tech_artifact a ON bc.product_id = a.id AND a.bool_delete_enum = 0 WHERE bc.bool_delete_enum = 0
AND bc.task_type_enum = #{productType}
AND bc.project_id = #{projectId}
GROUP BY DATE_FORMAT( bc.create_time, '%Y%m' ) ORDER BY month

SELECT complete.project_id, sum(complete.quantity * product.net_weight) mete FROM mes_building_complete complete LEFT JOIN tech_artifact product ON product.id = complete.product_id AND product.bool_delete_enum = 0 WHERE complete.task_type_enum = 2 AND complete.bool_delete_enum = 0
AND DATE_FORMAT(complete.create_time, '%Y') = #{year}
GROUP BY complete.project_id

SELECT * FROM mes_building_complete WHERE
( product_id= #{numberInfo.productId} and number=#{numberInfo.number})
AND bool_delete_enum = 0 AND task_type_enum=#{type}

SELECT c.project_id 'project.id', c.monomer_id 'monomer.id', c.area_id 'area.id', c.product_id 'productId', c.task_id 'taskId', c.create_time 'date', c.production_line_id 'productionLine.id', c.team_id 'teamId', sum( c.quantity ) quantity FROM `mes_building_complete` c LEFT JOIN tech_artifact artifact on artifact.id = c.product_id and artifact.bool_delete_enum = 0 WHERE c.bool_delete_enum = 0 AND c.task_type_enum = 2
AND c.create_time >= #{startTime}
AND c.create_time <= #{endTime}
AND c.project_id=#{projectId}
AND c.workshop_id=#{workShopId}
AND c.production_line_id=#{productionLineId}
AND artifact.name like concat('%',#{name},'%')
GROUP BY c.project_id, c.monomer_id, c.area_id, c.product_id, c.task_id, c.create_time, c.production_line_id, c.team_id

SELECT cp.short_name projectName, ROUND((IFNULL(sum(case when wr.product_type = 2 then wr.quantity * art.net_weight END),0) + IFNULL(sum(case when wr.product_type = 1 then wr.quantity * part.net_weight END),0) + IFNULL(sum(case when wr.product_type = 16 then wr.quantity * ass.net_weight END),0))/1000,2) inboundWeight FROM mes_building_warehouse_record wr LEFT JOIN contract_project cp ON wr.project_id = cp.id AND cp.bool_delete_enum = 0 LEFT JOIN tech_artifact art ON wr.product_id = art.id AND art.bool_delete_enum = 0 and wr.product_type = 2 LEFT JOIN tech_machine_part part ON wr.product_id = part.id AND part.bool_delete_enum = 0 and wr.product_type = 1 LEFT JOIN tech_assemble ass ON wr.project_id = ass.id AND ass.bool_delete_enum = 0 and wr.product_type = 16 WHERE wr.bool_delete_enum = 0 AND wr.type = 1 AND wr.bool_delete_enum = 0 AND wr.warehouse_type in(0,2,4) and wr.product_type in (1,2,16) AND wr.in_year_month_date = date_format(now(), '%Y-%m')
and wr.workshop_id = #{workshopId}
GROUP BY cp.short_name

SELECT ta.*, 1 as actualQuantity, cp.id 'project.id', cp.name 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', m.id 'monomer.id', m.name 'monomer.name', ar.id 'area.id', ar.name 'area.name', CASE WHEN tnl.artifact_task_process_id = 0 THEN '0' ELSE pro.id END AS 'process.id', CASE WHEN tnl.artifact_task_process_id = 0 THEN '已入库' ELSE pro.name END AS 'process.name' FROM tech_artifact ta left join contract_project cp on ta.project_id = cp.id and cp.bool_delete_enum = 0 left join plan_monomer m on ta.monomer_id = m.id and m.bool_delete_enum = 0 left join plan_area ar on ta.area_id = ar.id and ar.bool_delete_enum = 0 left join ( select artifact_id, artifact_number, artifact_task_process_id from mes_building_task_number_link where bool_delete_enum = 0 group by artifact_id, artifact_number, artifact_task_process_id ) tnl on tnl.artifact_id = ta.id left join mes_building_task_process mp on mp.id = tnl.artifact_task_process_id and mp.bool_delete_enum = 0 and mp.task_type_enum = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()} left join mes_building_process pro on pro.id = mp.process_id and pro.bool_delete_enum = 0 where ta.bool_delete_enum = 0 and ta.area_id = #{areaId} and tnl.artifact_task_process_id is not null
AND tnl.artifact_task_process_id = 0
AND mp.process_id = #{processId}

select
date_format(a.create_time, #{dateQueryFormat}) AS dateStr,
ifnull(sum( a.quantity * b.net_weight ),0) / 1000 AS value
FROM mes_building_complete a
left join tech_artifact b on a.product_id = b.id and a.bool_delete_enum = 0
and a.task_type_enum = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()}
where a.bool_delete_enum = 0

    and date_format(a.create_time, #{dateQueryFormat}) in
    
        #{dateStr}
    


    and a.workshop_id = #{workshopId}


    and a.team_id = #{teamId}

GROUP BY date_format(a.create_time, #{dateQueryFormat})

select
ifnull(sum( a.quantity * b.net_weight ),0) / 1000
FROM mes_building_complete a
left join tech_artifact b on a.product_id = b.id and a.bool_delete_enum = 0
and a.task_type_enum = ${@com.hzchum.scim.mes.building.core.api.enums.task.TaskTypeEnum@ARTIFACT.getType()}
where a.bool_delete_enum = 0

    and date_format(a.create_time, '%Y') = date_format(CURDATE(), '%Y')


    and date_format(a.create_time, '%Y-%m') = date_format(CURDATE(), '%Y-%m')


    AND DATE_FORMAT(a.create_time, '%Y-%m') = DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 MONTH), '%Y-%m');


    and YEARWEEK(date_format(a.create_time, '%Y-%m-%d'),1) = YEARWEEK(now(),1)


    and a.workshop_id = #{workshopId}


    and a.team_id = #{teamId}
